import re

def solve(env, goal):
    obs = env.observation
    # Extract room receptacles from initial observation
    room_obs = obs
    receptacles = []
    m = re.search(r"you see (.*?)\.", room_obs, re.I | re.S)
    if m:
        text = m.group(1)
        for part in re.split(r",\s*", text):
            part = part.strip()
            if not part or part.startswith("nothing"):
                continue
            # strip leading "a " or "an "
            part = re.sub(r"^(a|an)\s+", "", part, flags=re.I).strip()
            if part:
                receptacles.append(part)

    # Parse goal: put a clean <object> in <receptacle>
    gm = re.search(r"put a clean (.+?) in (.+?)\.", goal, re.I)
    if gm:
        target_obj = gm.group(1).strip()
        target_rec = gm.group(2).strip()
    else:
        gm2 = re.search(r"put a (.+?) in (.+?)\.", goal, re.I)
        if gm2:
            target_obj = gm2.group(1).strip()
            target_rec = gm2.group(2).strip()
        else:
            target_obj = "bowl"
            target_rec = "fridge"

    # Normalize target receptacle base name
    def rec_match(rec):
        return rec == target_rec or rec.startswith(target_rec + " ") or rec == target_rec + " 1"

    # Locate target receptacle
    target_rep = None
    for r in receptacles:
        if rec_match(r):
            target_rep = r
            break
    if target_rep is None:
        # fallback: try target_rec + " 1"
        for r in receptacles:
            if r.lower().startswith(target_rec.lower()):
                target_rep = r
                break
    if target_rep is None:
        target_rep = target_rec + " 1"

    # parse contents from observation text
    def parse_contents(text):
        res = []
        for line in text.split("."):
            line = line.strip()
            if not line:
                continue
            cm = re.search(r"(?:On|In) (?:the )?(.*?), you see (.*)$", line, re.I)
            if cm:
                container = cm.group(1).strip()
                items = cm.group(2)
                for it in re.split(r",\s*and\s*|\s*and\s*|,\s*", items):
                    it = it.strip().rstrip(".")
                    om = re.match(r"(?:a|an) (.*)", it, re.I)
                    if om:
                        res.append((om.group(1).strip(), container))
        return res

    def has_target(text):
        return re.search(r"\b(?:a|an) " + re.escape(target_obj) + r"\b", text, re.I) is not None

    def step(cmd):
        return env.step(cmd)

    def admissible():
        try:
            return env.admissible()
        except Exception:
            return []

    def find_exact_name(text, base):
        # find exact object name like "bowl 2"
        for obj, cont in parse_contents(text):
            if obj.lower() == base.lower() or obj.lower().startswith(base.lower() + " "):
                return obj
        # fallback regex
        om = re.search(r"\b" + re.escape(base) + r"(?: \d+)?\b", text, re.I)
        if om:
            return om.group(0)
        return base

    # State
    have_obj = False
    target_obj_actual = target_obj
    found = False
    obj_container = None
    obj_location = None

    # Check if already holding
    current = env.observation
    if re.search(r"You are carrying", current, re.I) and has_target(current):
        have_obj = True
        target_obj_actual = find_exact_name(current, target_obj)

