        for obj, cont in contents:
            if obj.lower() == target_obj.lower() or obj.lower().startswith(target_obj.lower() + " "):
                found = True
                obj_container = cont
                obj_location = rec
                target_obj_actual = obj
                break
        if found:
            break
        # fallback: if obs mentions target directly
        if has_target(obs):
            # determine container from obs
            on_m = re.search(r"On the (.*?), you see", obs, re.I)
            if on_m:
                obj_container = on_m.group(1).strip()
            else:
                obj_container = rec
            obj_location = rec
            found = True
            target_obj_actual = find_exact_name(obs, target_obj)
            break

    # If not found, check target receptacle
    if not found:
        step("go to " + target_rep)
        obs = env.observation
        if re.search(r"is closed", obs, re.I):
            if ("open " + target_rep) in admissible():
                step("open " + target_rep)
                obs = env.observation
        contents = parse_contents(obs)
