            if obj.lower() == target_obj.lower() or obj.lower().startswith(target_obj.lower() + " "):
                found = True
                obj_container = cont
                obj_location = target_rep
                target_obj_actual = obj
                break
        if not found and has_target(obs):
            on_m = re.search(r"On the (.*?), you see", obs, re.I)
            if on_m:
                obj_container = on_m.group(1).strip()
            else:
                obj_container = target_rep
            obj_location = target_rep
            found = True
            target_obj_actual = find_exact_name(obs, target_obj)

    # If still not found, check if carried
    if not found:
        obs = env.observation
        if re.search(r"You are carrying", obs, re.I) and has_target(obs):
            have_obj = True
            target_obj_actual = find_exact_name(obs, target_obj)
            found = True

    # Take object if not held
    if found and not have_obj:
        if obj_container is None:
            obj_container = obj_location if obj_location else target_rep
        step("go to " + obj_container)
        obs = env.observation
        if re.search(r"is closed", obs, re.I):
            if ("open " + obj_container) in admissible():
                step("open " + obj_container)
                obs = env.observation
        # determine exact name again from current obs
        target_obj_actual = find_exact_name(obs, target_obj)
        # try take
        take_cmd = "take " + target_obj_actual + " from " + obj_container
        if take_cmd not in admissible():
            # try using obj_location
            if obj_location:
                alt = "take " + target_obj_actual + " from " + obj_location
                if alt in admissible():
                    take_cmd = alt
                else:
                    take_cmd = None
            else:
                take_cmd = None
        if take_cmd and take_cmd in admissible():
            step(take_cmd)
            obs = env.observation
            have_obj = True
        else:
            # fallback: maybe object is already held? or try "take X"
            simple = "take " + target_obj_actual
            if simple in admissible():
                step(simple)
                have_obj = True
            else:
                # maybe it's already in inventory? check obs
                if re.search(r"You are carrying", obs, re.I) and has_target(obs):
                    have_obj = True

    # Clean object
    sink = None
    for r in receptacles:
        if "sink" in r.lower():
            sink = r
            break
