        step("go to " + sink)
        obs = env.observation
        clean_cmd = "clean " + target_obj_actual + " with " + sink
        if clean_cmd in admissible():
            step(clean_cmd)
            obs = env.observation
        else:
            # try without "with"? not standard; maybe just "clean X"
            simple = "clean " + target_obj_actual
            if simple in admissible():
                step(simple)

    # Move to target receptacle
    step("go to " + target_rep)
    obs = env.observation
    if re.search(r"is closed", obs, re.I):
        if ("open " + target_rep) in admissible():
            step("open " + target_rep)
            obs = env.observation
    move_cmd = "move " + target_obj_actual + " to " + target_rep
    if move_cmd in admissible():
        step(move_cmd)
    else:
        put_cmd = "put " + target_obj_actual + " in " + target_rep
        if put_cmd in admissible():
            step(put_cmd)
